const assert=require('node:assert/strict');
const {chromium}=require('/Users/xiaohong.zhxh/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{const base=process.argv[2];const control=async value=>fetch(base+'/__control',{method:'POST',body:JSON.stringify(value)});const b=await chromium.launch({executablePath:'/Users/xiaohong.zhxh/Library/Caches/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-mac-arm64/chrome-headless-shell'});try{
const p=await b.newPage({viewport:{width:390,height:844}});await control({directoryName:'服务端验收目录-蓝莓'});await p.goto(base+'/');await p.locator('#name:enabled').waitFor();assert.equal(await p.locator('#directory option').textContent(),'服务端验收目录-蓝莓');
await p.locator('#name').fill('样例产品');await p.screenshot({path:__dirname+'/implementation.png'});
const geometry=await p.locator('.group,footer').evaluateAll(nodes=>nodes.map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]}));const ref=await b.newPage({viewport:{width:390,height:844}});await ref.goto(base+'/prototype');assert.deepEqual(geometry,await ref.locator('.group,footer').evaluateAll(nodes=>nodes.map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})));await ref.close();
await p.locator('#name').fill('蓝莓产品-73');await p.getByRole('button',{name:'保存草稿'}).click();await p.getByRole('status').filter({hasText:'保存成功'}).waitFor();await p.reload();await p.locator('#name:enabled').waitFor();assert.equal(await p.locator('#name').inputValue(),'蓝莓产品-73');assert.equal(await p.locator('#directory option:checked').textContent(),'服务端验收目录-蓝莓');await p.screenshot({path:__dirname+'/readback.png'});
await control({rejectSave:true});await p.locator('#name').fill('拒绝保存-94');await p.getByRole('button',{name:'保存草稿'}).click();await p.getByRole('status').filter({hasText:'保存暂不可用'}).waitFor();assert.equal(await p.locator('#name').inputValue(),'拒绝保存-94');assert(!await p.getByRole('status').textContent().then(x=>x.includes('成功')));await p.screenshot({path:__dirname+'/failure.png'});await p.reload();await p.locator('#name:enabled').waitFor();assert.equal(await p.locator('#name').inputValue(),'蓝莓产品-73');await control({rejectSave:false});
for(const value of [{name:' ',directoryId:await p.locator('#directory').inputValue()},{name:'bad',directoryId:'nonexistent'}]){const r=await fetch(base+'/api/item',{method:'POST',body:JSON.stringify(value)});assert.equal(r.status,400);}
const state=await fetch(base+'/__inspect').then(r=>r.json());assert.equal(state.item.name,'蓝莓产品-73');assert(state.requests.some(r=>r.method==='POST'));await p.goto(base+'/settings');await p.goto(base+'/');await p.locator('#name:enabled').waitFor();await p.getByRole('button',{name:'返回',exact:true}).click();await p.waitForURL(base+'/settings');assert.equal(await p.locator('#service').textContent(),'现有服务');console.log(JSON.stringify({result:'PASS',geometry,item:state.item,requestCount:state.requests.length}));
}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
